{
  "up": "Select molecule_chembl_id as compound_chembl_id, canonical_smiles from molecule_dictionary join activities on molecule_dictionary.molregno = activities.molregno join assays on activities.assay_id = assays.assay_id join target_dictionary on assays.tid = target_dictionary.tid where target_dictionary.tid = 2842 and activities.standard_relation = '=' and activities.standard_value is not null and activities.standard_units = 'nM' join compound_structures on molecule_dictionary.molregno = compound_structures.molregno where molecule_dictionary.chembl_id = 'CHEMBL2842' order by molecule_chembl_id asc limit 1000"
}
